	// Payload: ChannelArchivePayload.
	MessageChannelArchive = "channelArchive"
	// A channel was created.
	// Payload: ChannelCreatedPayload.
	MessageChannelCreated = "channelCreated"
	// A channel was deleted.
	// Payload: ChannelDeletedPayload.
	MessageChannelDeleted = "channelDeleted"
	// Bulk updates were made to a channel's history.
	// Payload: ChannelHistoryChangedPayload.
	MessageChannelHistoryChanged = "channelHistoryChanged"
	// You joined a channel.
	// Payload: ChannelJoinedPayload.
	MessageChannelJoined = "channelJoined"
	// You left a channel.
	// Payload: ChannelLeftPayload.
	MessageChannelLeft = "channelLeft"
	// Your channel read marker was updated.
	// Payload: ChannelMarkedPayload.
	MessageChannelMarked = "channelMarked"
	// A channel was renamed.
	// Payload: ChannelRenamePayload.
	MessageChannelRename = "channelRename"
	// A channel was unarchived.
	// Payload: ChannelUnarchivePayload.
	MessageChannelUnarchive = "channelUnarchive"
	// A slash command has been added or changed.
	// Payload: CommandsChangedPayload.
	MessageCommandsChanged = "commandsChanged"
	// Do not Disturb settings changed for the current user.
	// Payload: DndUpdatedPayload.
	MessageDndUpdated = "dndUpdated"
	// Do not Disturb settings changed for a member.
	// Payload: DndUpdatedUserPayload.
	MessageDndUpdatedUser = "dndUpdatedUser"
	// The workspace email domain has changed.
