	MessageEmojiRemoved = "emojiRemoved"
	// A custom emoji has been added.
	// Payload: EmojiAddedPayload.
	MessageEmojiAdded = "emojiAdded"
	// A file was changed.
	// Payload: FileChangePayload.
	MessageFileChange = "fileChange"
